package io.github.g20ir.db

import io.github.g20ir.ir.IrSignal
import io.github.g20ir.ir.Protocol
import io.github.g20ir.model.CodeSet
import io.github.g20ir.model.G20Key
import org.json.JSONObject

/** The bundled code database (assets/irdb.json, generated by tools/build_irdb.py). */
class CodeDatabase(json: String) {
    private val root = JSONObject(json)
    private val db = root.getJSONObject("db")
    val source: String = root.getJSONObject("meta").optString("source")

    val categories: List<String> = db.keys().asSequence().toList()

    /** Brands of a category, the ones with the most known models first. */
    fun brands(category: String): List<Brand> {
        val c = db.optJSONObject(category) ?: return emptyList()
        return c.keys().asSequence().map { name ->
            val arr = c.getJSONArray(name)
            var models = 0
            for (i in 0 until arr.length()) models += arr.getJSONObject(i).getJSONArray("m").length()
            Brand(name, arr.length(), models)
        }.sortedWith(compareByDescending<Brand> { it.models }.thenBy { it.name.lowercase() }).toList()
    }

    fun codeSets(category: String, brand: String): List<CodeSet> {
        val arr = db.optJSONObject(category)?.optJSONArray(brand)
        val fromDb = if (arr == null) emptyList() else List(arr.length()) { CodeSet.fromJson(brand, category, arr.getJSONObject(it)) }
        return builtIn(category, brand) + fromDb
    }

    /**
     * Code sets not in Flipper-IRDB, for Denon AV receivers:
     *  1. AVR-X (RC-1220 / RC-1253 remotes): Kaseikyo, Denon vendor address 0x325441, from
     *     Flipper-IRDB's Denon_RC1253 / AVR-2113CI files. Power 5 is the remote's toggle; every
     *     input has its own code, offered as alternatives for the Input key. ~208 bytes each.
     *  2. The codes Google TV's own "Set up remote buttons" writes for Denon receivers (captured
     *     from a G20, see tools/legacy/dec.py): Denon protocol, address 2. 136 bytes each.
     *     On the owner's AVR-X3300W, 193 only switches off and 225 switches on.
     * Both are over 128 bytes, so remotes with a small MTU need long writes.
     */
    private fun builtIn(category: String, brand: String): List<CodeSet> {
        if (category != "AV receiver" || !brand.equals("Denon", ignoreCase = true)) return emptyList()
        return listOf(denonAvrX(brand, category), denonGoogle(brand, category))
    }

    data class Brand(val name: String, val codeSets: Int, val models: Int)

    companion object {
        const val DENON_KASEIKYO_ADDRESS = 0x325441L

        /** Main-zone inputs of Denon AVR-X receivers (Kaseikyo commands). */
        val DENON_INPUTS: List<Pair<String, Long>> = listOf(
            "CBL/SAT" to 0x2D3, "DVD" to 0x2D0, "Blu-ray" to 0x2D1, "Game" to 0x2D5,
            "Media Player" to 0x2D6, "TV Audio" to 0x2D2, "AUX1" to 0x2D9, "AUX2" to 0x2DA,
            "CD" to 0x2C2, "Phono" to 0x2C0, "Tuner" to 0x2CF, "Bluetooth" to 0x2EF,
            "HEOS Music / Network" to 0x2C7, "USB / iPod" to 0x2CE, "Internet Radio" to 0x2E5,
        ).map { it.first to it.second.toLong() }

        private fun k(cmd: Long): IrSignal = IrSignal.Parsed(Protocol.Kaseikyo, DENON_KASEIKYO_ADDRESS, cmd)
        private fun d(cmd: Long): IrSignal = IrSignal.Parsed(Protocol.Denon, 2, cmd)

        fun denonAvrX(brand: String = "Denon", category: String = "AV receiver"): CodeSet {
            val names = mutableMapOf(
                k(5) to "Power toggle",
                d(225) to "Power on only (Denon code)",
                d(193) to "Power off (Denon code)",
                k(0x170) to "Volume +", k(0x171) to "Volume −", k(0x172) to "Mute",
            )
            val inputs = DENON_INPUTS.map { (name, cmd) -> k(cmd).also { names[it] = "Input $name" } }
            return CodeSet(
                brand, category, listOf("Denon AVR-X (RC-1220, RC-1253)", "AVR-X3300W", "AVR-X2000+"),
                mapOf(
                    G20Key.POWER to listOf(k(5), d(225), d(193)),
                    G20Key.INPUT to inputs,
                    G20Key.VOL_UP to listOf(k(0x170)),
                    G20Key.VOL_DOWN to listOf(k(0x171)),
                    G20Key.MUTE to listOf(k(0x172)),
                ),
                names,
            )
        }

        fun denonGoogle(brand: String = "Denon", category: String = "AV receiver"): CodeSet = CodeSet(
            brand, category, listOf("Denon AVR (Google TV codes)"),
            mapOf(
                G20Key.POWER to listOf(d(193), d(225), d(226)),
                G20Key.VOL_UP to listOf(d(241)),
                G20Key.VOL_DOWN to listOf(d(242)),
                G20Key.MUTE to listOf(d(240)),
            ),
            mapOf(
                d(193) to "Power toggle (switches off only on AVR-X)", d(225) to "Power on only",
                d(226) to "Power off only", d(241) to "Volume +", d(242) to "Volume −", d(240) to "Mute",
            ),
        )
    }
}
